// token bucket: refills 2 tokens per second, holds at most 5
const CAP = 5;
const RATE = 2;

export function makeBucket() {
  return { tokens: CAP, last: 0 };
}

export function allow(b, nowSec) {
  b.tokens = Math.min(CAP, b.tokens + (nowSec - b.last) * RATE);
  b.last = nowSec;
  if (b.tokens >= 1) {
    b.tokens -= 1;
    return true;
  }
  return false;
}

